// ============================================================================
//  reference_unfused.cu -- hand-written, unfused reference implementation of
//
//      out = attention(Q,K,V) -> MLP(W1, relu, W2, b1, b2)
//
//  This file is deliberately NOT generated by the compiler. It exists so the generated
//  kernels can be checked against an independent implementation of the same math, and so
//  the fused output can be compared with a hand-written unfused baseline.
//
//  Structure mirrors the compiler's --no-fusion mode: one kernel per IR op, with the
//  attention scale folded into the score GEMM (exactly as the compiler folds it):
//
//      out.attn_scores = matmul_nt(Q,K) * 1/sqrt(D)   [fp32 storage, promoted for softmax]
//      out.attn_softmax = softmax(out.attn_scores)
//      out.attn_pv     = matmul(out.attn_softmax, V)
//      out.mlp_fc1     = matmul(out.attn_pv, W1)
//      out.mlp_b1      = out.mlp_fc1 + b1
//      out.mlp_act     = relu(out.mlp_b1)
//      out.mlp_fc2     = matmul(out.mlp_act, W2)
//      out.mlp_b2      = out.mlp_fc2 + b2                (final output)
//
//  Numeric policy matches the compiler: FP16 storage, FP32 accumulation; the tiling is
//  intentionally different from the compiler's (32x32 tile, 128 threads) so the two are
//  not copies of each other.
//
//  build:  nvcc -arch=sm_61 -O3 -Xptxas -v reference_unfused.cu -o reference_unfused
//  run:    reference_unfused --inputs <dir> --out out.bin --timings t.csv --iters 100
// ============================================================================
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define SEQ 64
#define DIM 256
#define FFD 1024

#define CK(x) do { cudaError_t e = (x); if (e != cudaSuccess) { \
    fprintf(stderr, "CUDA error %s (%d) at line %d\n", cudaGetErrorString(e), (int) e, __LINE__); \
    exit(2); } } while (0)

// ------------------------------------------------------------------ reductions
__device__ __forceinline__ float warp_max(float v) {
#pragma unroll
    for (int o = 16; o > 0; o >>= 1) v = fmaxf(v, __shfl_down_sync(0xffffffffu, v, o));
    return v;
}

__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
    for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffffu, v, o);
    return v;
}

__device__ __forceinline__ float block_max(float v, float* scratch) {
    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    const int warps = (blockDim.x + 31) >> 5;
    v = warp_max(v);
    if (lane == 0) scratch[warp] = v;
    __syncthreads();
    if (warp == 0) {
        float t = (lane < warps) ? scratch[lane] : -INFINITY;
        t = warp_max(t);
        if (lane == 0) scratch[0] = t;
    }
    __syncthreads();
    const float r = scratch[0];
    __syncthreads();
    return r;
}

__device__ __forceinline__ float block_sum(float v, float* scratch) {
    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
    const int warps = (blockDim.x + 31) >> 5;
    v = warp_sum(v);
    if (lane == 0) scratch[warp] = v;
    __syncthreads();
    if (warp == 0) {
        float t = (lane < warps) ? scratch[lane] : 0.0f;
        t = warp_sum(t);
        if (lane == 0) scratch[0] = t;
    }
    __syncthreads();
    const float r = scratch[0];
    __syncthreads();
    return r;
}

// ------------------------------------------------------------------ tiled GEMM
// A: [M,K] row major. B: [K,N] when transB==0, [N,K] when transB==1.
// C: [M,N] as FP16 (HALF_OUT) or FP32 -- the compiler promotes the softmax input to FP32,
// so the reference does the same for the score matrix.
// FP16 operands staged in shared memory, FP32 accumulate, optional epilogue scale.
template <int BM, int BN, int BK, int TX, int TY, bool HALF_OUT>
__global__ void ref_gemm(const __half* __restrict__ A, const __half* __restrict__ B,
                         void* __restrict__ Cv, int M, int N, int K, int transB, float scale) {
    const int TM = BM / TY;
    const int TN = BN / TX;
    __shared__ __half As[BM][BK];
    __shared__ __half Bs[BK][BN];
    const int tx = threadIdx.x % TX;
    const int ty = threadIdx.x / TX;
    const int rowBase = blockIdx.y * BM;
    const int colBase = blockIdx.x * BN;
    float acc[TM][TN];
    for (int i = 0; i < TM; ++i)
        for (int j = 0; j < TN; ++j) acc[i][j] = 0.0f;

    for (int k0 = 0; k0 < K; k0 += BK) {
        for (int t = threadIdx.x; t < BM * BK; t += TX * TY) {
            const int r = t / BK, c = t % BK;
            const int gr = rowBase + r, gc = k0 + c;
            As[r][c] = (gr < M && gc < K) ? A[gr * K + gc] : __float2half(0.0f);
        }
        for (int t = threadIdx.x; t < BK * BN; t += TX * TY) {
            const int r = t / BN, c = t % BN;
            const int gr = k0 + r, gc = colBase + c;
            __half v = __float2half(0.0f);
            if (gr < K && gc < N) v = transB ? B[gc * K + gr] : B[gr * N + gc];
            Bs[r][c] = v;
        }
        __syncthreads();
        for (int kk = 0; kk < BK; ++kk) {
            float a[TM], b[TN];
            for (int i = 0; i < TM; ++i) a[i] = __half2float(As[ty * TM + i][kk]);
            for (int j = 0; j < TN; ++j) b[j] = __half2float(Bs[kk][tx * TN + j]);
            for (int i = 0; i < TM; ++i)
                for (int j = 0; j < TN; ++j) acc[i][j] += a[i] * b[j];
        }
        __syncthreads();
    }
    for (int i = 0; i < TM; ++i) {
        for (int j = 0; j < TN; ++j) {
            const int r = rowBase + ty * TM + i, c = colBase + tx * TN + j;
            if (r < M && c < N) {
                if (HALF_OUT) {
                    ((__half*) Cv)[r * N + c] = __float2half(acc[i][j] * scale);
                } else {
                    ((float*) Cv)[r * N + c] = acc[i][j] * scale;
                }
            }
        }
    }
}

// ------------------------------------------------------------------ softmax
__global__ void ref_softmax(const float* __restrict__ in, __half* __restrict__ out, int rows, int cols) {
    __shared__ float scratch[32];
    const int row = blockIdx.x;
    float m = -INFINITY;
    for (int j = threadIdx.x; j < cols; j += blockDim.x) m = fmaxf(m, in[(long) row * cols + j]);
    m = block_max(m, scratch);
    float s = 0.0f;
    for (int j = threadIdx.x; j < cols; j += blockDim.x) s += expf(in[(long) row * cols + j] - m);
    s = block_sum(s, scratch);
    const float inv = 1.0f / s;
    for (int j = threadIdx.x; j < cols; j += blockDim.x) {
        out[(long) row * cols + j] = __float2half(expf(in[(long) row * cols + j] - m) * inv);
    }
}

// ------------------------------------------------------------------ elementwise
// mode 0: dst = src + b (row-broadcast bias), 1: dst = relu(src)
__global__ void ref_elementwise(__half* __restrict__ dst, const __half* __restrict__ src,
                                const float* __restrict__ b, int rows, int cols, int mode) {
    const long i = (long) blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= (long) rows * cols) return;
    float v = __half2float(src[i]);
    if (mode == 0) v += b[i % cols];
    if (mode == 1) v = fmaxf(v, 0.0f);
    dst[i] = __float2half(v);
}

// ------------------------------------------------------------------ host side
typedef struct {
    const char* name;
    void* dev;
    long elems;
    int esize;
    int hostIndex;   // -1 = produced on device
} tensor_t;

static tensor_t g_tensors[] = {
    {"Q",    NULL, (long) SEQ * DIM, 2, 0},
    {"K",    NULL, (long) SEQ * DIM, 2, 1},
    {"V",    NULL, (long) SEQ * DIM, 2, 2},
    {"W1",   NULL, (long) DIM * FFD, 2, 3},
    {"b1",   NULL, FFD,              4, 4},
    {"W2",   NULL, (long) FFD * DIM, 2, 5},
    {"b2",   NULL, DIM,              4, 6},
    {"out.attn_scores",  NULL, (long) SEQ * SEQ, 4, -1},
    {"out.attn_softmax", NULL, (long) SEQ * SEQ, 2, -1},
    {"out.attn_pv",      NULL, (long) SEQ * DIM, 2, -1},
    {"out.mlp_fc1",      NULL, (long) SEQ * FFD, 2, -1},
    {"out.mlp_b1",       NULL, (long) SEQ * FFD, 2, -1},
    {"out.mlp_act",      NULL, (long) SEQ * FFD, 2, -1},
    {"out.mlp_fc2",      NULL, (long) SEQ * DIM, 2, -1},
    {"out.mlp_b2",       NULL, (long) SEQ * DIM, 2, -1},
};
#define N_TENSORS ((int) (sizeof(g_tensors) / sizeof(g_tensors[0])))
#define T_Q 0
#define T_K 1
#define T_V 2
#define T_W1 3
#define T_B1 4
#define T_W2 5
#define T_B2 6
#define T_SCORES 7
#define T_PROBS 8
#define T_PV 9
#define T_FC1 10
#define T_B1A 11
#define T_ACT 12
#define T_FC2 13
#define T_OUT 14

static const char* REGIONS[] = {
    "out.attn_scores", "out.attn_softmax", "out.attn_pv",
    "out.mlp_fc1", "out.mlp_b1", "out.mlp_act", "out.mlp_fc2", "out.mlp_b2",
};
#define N_REGIONS ((int) (sizeof(REGIONS) / sizeof(REGIONS[0])))

static const char* KERNELS[] = {
    "ref_gemm_nt_scaled", "ref_softmax", "ref_gemm_nn",
    "ref_gemm_fc1", "ref_bias_b1", "ref_relu_act", "ref_gemm_fc2", "ref_bias_b2",
};

static const void* KERNEL_PTRS[] = {
    (const void*) (ref_gemm<32, 32, 32, 16, 8, false>),
    (const void*) ref_softmax,
    (const void*) (ref_gemm<32, 32, 32, 16, 8, true>),
    (const void*) (ref_gemm<32, 32, 32, 16, 8, true>),
    (const void*) ref_elementwise,
    (const void*) ref_elementwise,
    (const void*) (ref_gemm<32, 32, 32, 16, 8, true>),
    (const void*) ref_elementwise,
};
#define N_KERNELS ((int) (sizeof(KERNELS) / sizeof(KERNELS[0])))

static void launch_regions(cudaEvent_t* evStart, cudaEvent_t* evStop, int measure) {
    const dim3 g2 = dim3((SEQ + 31) / 32, (SEQ + 31) / 32);
    if (measure) CK(cudaEventRecord(evStart[0], 0));
    ref_gemm<32, 32, 32, 16, 8, false><<<g2, 128>>>((const __half*) g_tensors[T_Q].dev,
        (const __half*) g_tensors[T_K].dev, (void*) g_tensors[T_SCORES].dev,
        SEQ, SEQ, DIM, 1, 1.0f / sqrtf((float) DIM));
    if (measure) CK(cudaEventRecord(evStop[0], 0));

    if (measure) CK(cudaEventRecord(evStart[1], 0));
    ref_softmax<<<SEQ, 64>>>((const float*) g_tensors[T_SCORES].dev,
        (__half*) g_tensors[T_PROBS].dev, SEQ, SEQ);
    if (measure) CK(cudaEventRecord(evStop[1], 0));

    if (measure) CK(cudaEventRecord(evStart[2], 0));
    ref_gemm<32, 32, 32, 16, 8, true><<<dim3((DIM + 31) / 32, (SEQ + 31) / 32), 128>>>(
        (const __half*) g_tensors[T_PROBS].dev, (const __half*) g_tensors[T_V].dev,
        (void*) g_tensors[T_PV].dev, SEQ, DIM, SEQ, 0, 1.0f);
    if (measure) CK(cudaEventRecord(evStop[2], 0));

    if (measure) CK(cudaEventRecord(evStart[3], 0));
    ref_gemm<32, 32, 32, 16, 8, true><<<dim3((FFD + 31) / 32, (SEQ + 31) / 32), 128>>>(
        (const __half*) g_tensors[T_PV].dev, (const __half*) g_tensors[T_W1].dev,
        (void*) g_tensors[T_FC1].dev, SEQ, FFD, DIM, 0, 1.0f);
    if (measure) CK(cudaEventRecord(evStop[3], 0));

    const long nHidden = (long) SEQ * FFD;
    const int blocksHidden = (int) ((nHidden + 255) / 256);
    if (measure) CK(cudaEventRecord(evStart[4], 0));
    ref_elementwise<<<blocksHidden, 256>>>((__half*) g_tensors[T_B1A].dev,
        (const __half*) g_tensors[T_FC1].dev, (const float*) g_tensors[T_B1].dev, SEQ, FFD, 0);
    if (measure) CK(cudaEventRecord(evStop[4], 0));

    if (measure) CK(cudaEventRecord(evStart[5], 0));
    ref_elementwise<<<blocksHidden, 256>>>((__half*) g_tensors[T_ACT].dev,
        (const __half*) g_tensors[T_B1A].dev, NULL, SEQ, FFD, 1);
    if (measure) CK(cudaEventRecord(evStop[5], 0));

    if (measure) CK(cudaEventRecord(evStart[6], 0));
    ref_gemm<32, 32, 32, 16, 8, true><<<dim3((DIM + 31) / 32, (SEQ + 31) / 32), 128>>>(
        (const __half*) g_tensors[T_ACT].dev, (const __half*) g_tensors[T_W2].dev,
        (void*) g_tensors[T_FC2].dev, SEQ, DIM, FFD, 0, 1.0f);
    if (measure) CK(cudaEventRecord(evStop[6], 0));

    const long nOut = (long) SEQ * DIM;
    const int blocksOut = (int) ((nOut + 255) / 256);
    if (measure) CK(cudaEventRecord(evStart[7], 0));
    ref_elementwise<<<blocksOut, 256>>>((__half*) g_tensors[T_OUT].dev,
        (const __half*) g_tensors[T_FC2].dev, (const float*) g_tensors[T_B2].dev, SEQ, DIM, 0);
    if (measure) CK(cudaEventRecord(evStop[7], 0));
    CK(cudaGetLastError());
}

int main(int argc, char** argv) {
    const char* inputDir = NULL;
    const char* outFile = NULL;
    const char* timingFile = NULL;
    int iters = 100, warmup = 20, device = 0;
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--inputs") && i + 1 < argc) inputDir = argv[++i];
        else if (!strcmp(argv[i], "--out") && i + 1 < argc) outFile = argv[++i];
        else if (!strcmp(argv[i], "--timings") && i + 1 < argc) timingFile = argv[++i];
        else if (!strcmp(argv[i], "--iters") && i + 1 < argc) iters = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--warmup") && i + 1 < argc) warmup = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--device") && i + 1 < argc) device = atoi(argv[++i]);
        else { fprintf(stderr, "unknown argument '%s'\n", argv[i]); return 1; }
    }
    CK(cudaSetDevice(device));
    cudaDeviceProp prop;
    CK(cudaGetDeviceProperties(&prop, device));
    printf("DEVICE,%s,%d.%d,%d,%d,%d,%d,%d,%d\n", prop.name, prop.major, prop.minor,
           prop.multiProcessorCount, prop.regsPerMultiprocessor, (int) prop.sharedMemPerBlock,
           (int) prop.sharedMemPerMultiprocessor, prop.maxThreadsPerMultiProcessor, prop.clockRate);

    for (int i = 0; i < N_TENSORS; ++i) {
        CK(cudaMalloc(&g_tensors[i].dev, g_tensors[i].elems * g_tensors[i].esize));
    }
    if (inputDir) {
        for (int i = 0; i < N_TENSORS; ++i) {
            if (g_tensors[i].hostIndex < 0) continue;
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s.bin", inputDir, g_tensors[i].name);
            FILE* f = fopen(path, "rb");
            if (!f) { fprintf(stderr, "cannot open '%s'\n", path); return 3; }
            const long bytes = g_tensors[i].elems * g_tensors[i].esize;
            void* host = malloc((size_t) bytes);
            const size_t got = fread(host, 1, (size_t) bytes, f);
            fclose(f);
            if (got != (size_t) bytes) { fprintf(stderr, "short read on '%s'\n", path); return 3; }
            CK(cudaMemcpy(g_tensors[i].dev, host, (size_t) bytes, cudaMemcpyHostToDevice));
            free(host);
        }
    }

    for (int k = 0; k < N_KERNELS; ++k) {
        cudaFuncAttributes attr;
        if (cudaFuncGetAttributes(&attr, KERNEL_PTRS[k]) == cudaSuccess) {
            printf("KERNELATTR,%s,%d,%d,%d,%d\n", KERNELS[k], attr.numRegs,
                   (int) attr.sharedSizeBytes, (int) attr.localSizeBytes, attr.maxThreadsPerBlock);
        }
    }

    for (int i = 0; i < warmup; ++i) launch_regions(NULL, NULL, 0);
    CK(cudaDeviceSynchronize());

    cudaEvent_t rs[N_REGIONS], re[N_REGIONS];
    double regionMs[N_REGIONS];
    for (int r = 0; r < N_REGIONS; ++r) {
        CK(cudaEventCreate(&rs[r]));
        CK(cudaEventCreate(&re[r]));
        regionMs[r] = 0.0;
    }
    for (int it = 0; it < iters; ++it) {
        launch_regions(rs, re, 1);
        CK(cudaDeviceSynchronize());
        for (int r = 0; r < N_REGIONS; ++r) {
            float ms = 0.0f;
            CK(cudaEventElapsedTime(&ms, rs[r], re[r]));
            regionMs[r] += ms;
        }
    }

    cudaEvent_t t0, t1;
    CK(cudaEventCreate(&t0));
    CK(cudaEventCreate(&t1));
    for (int i = 0; i < warmup; ++i) launch_regions(NULL, NULL, 0);
    CK(cudaDeviceSynchronize());
    CK(cudaEventRecord(t0, 0));
    for (int it = 0; it < iters; ++it) launch_regions(NULL, NULL, 0);
    CK(cudaEventRecord(t1, 0));
    CK(cudaEventSynchronize(t1));
    float totalMs = 0.0f;
    CK(cudaEventElapsedTime(&totalMs, t0, t1));

    for (int r = 0; r < N_REGIONS; ++r) {
        printf("REGION,%s,%.6f\n", REGIONS[r], regionMs[r] / iters);
    }
    printf("TOTAL,%.6f\n", totalMs / iters);

    const long outElems = (long) SEQ * DIM;
    __half* hostOut = (__half*) malloc((size_t) outElems * 2);
    CK(cudaMemcpy(hostOut, g_tensors[T_OUT].dev, (size_t) outElems * 2, cudaMemcpyDeviceToHost));
    double checksum = 0.0;
    for (long i = 0; i < outElems; ++i) checksum += (double) __half2float(hostOut[i]);
    printf("CHECKSUM,%.9f\n", checksum);
    printf("OUTPUT,out.mlp_b2,%ld,2\n", outElems);
    if (outFile) {
        FILE* f = fopen(outFile, "wb");
        if (!f) { fprintf(stderr, "cannot write '%s'\n", outFile); return 3; }
        fwrite(hostOut, 1, (size_t) outElems * 2, f);
        fclose(f);
    }
    if (timingFile) {
        FILE* f = fopen(timingFile, "w");
        if (f) {
            fprintf(f, "region,ms_per_iter\n");
            for (int r = 0; r < N_REGIONS; ++r) {
                fprintf(f, "\"%s\",%.6f\n", REGIONS[r], regionMs[r] / iters);
            }
            fprintf(f, "\"TOTAL\",%.6f\n", totalMs / iters);
            fclose(f);
        }
    }
    free(hostOut);
    for (int i = 0; i < N_TENSORS; ++i) cudaFree(g_tensors[i].dev);
    return 0;
}
